
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_revm06_l_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_revm06_l", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-9.799114618942907e-02, -9.693393161661473e-02, -9.540433900171978e-02, -9.318664914613610e-02, -8.996344920596527e-02, -8.526880150200310e-02, -7.843135535256807e-02, -6.852673054351775e-02, -5.418918766305245e-02, -3.126801359482171e-02, 3.725176707431731e-03, -4.919205407932883e-02, -3.620870824984262e-02, -2.578870663169375e-02, -1.042040051326244e-02, 1.370042188962733e-02, 2.790892366143588e-02, 9.539177529367499e-03, 1.043646865222794e-03, 3.840456933070284e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


